#import "MenuScripts.h"

@implementation MenuScripts
+ (NSString *)menuProbeScript {
    return @"var menuProbeDone=false;"
      "function summarizeMenuState(){var layers=document.getElementById('layers');var profile=document.querySelector('[data-testid=DashButton_ProfileIcon_Link]');return {layersChildren:layers?layers.children.length:-1,bodyChildren:document.body?document.body.children.length:-1,profileExpanded:profile?(profile.getAttribute('aria-expanded')||''):'',dialogs:document.querySelectorAll('[role=dialog]').length,menus:document.querySelectorAll('[role=menu]').length};}"
      "var menuLifecycleOpenSeen=false,menuLifecycleCloseSeen=false;"
      "function menuLayerSnapshot(label){var layers=document.getElementById('layers'),kids=layers?Array.from(layers.children):[];send('menu-layer-lifecycle',{label:label,state:summarizeMenuState(),layerChildren:kids.map(function(el,i){return {index:i,tag:el.tagName||'',childCount:el.children?el.children.length:0,hidden:!!el.hidden,ariaHidden:el.getAttribute?el.getAttribute('aria-hidden'):null,display:getComputedStyle(el).display,visibility:getComputedStyle(el).visibility,opacity:getComputedStyle(el).opacity};})});}"
      "var menuLifecycleObserver=null;if((window.__scarletXDiagnostics||{}).menu){menuLifecycleObserver=new MutationObserver(function(){var s=summarizeMenuState();if(!menuLifecycleOpenSeen&&s.profileExpanded==='true'&&s.dialogs>0){menuLifecycleOpenSeen=true;menuLayerSnapshot('opened');}if(menuLifecycleOpenSeen&&!menuLifecycleCloseSeen&&s.profileExpanded!=='true'&&s.dialogs===0){menuLifecycleCloseSeen=true;menuLayerSnapshot('closed-immediate');setTimeout(function(){menuLayerSnapshot('closed-100ms');},100);setTimeout(function(){menuLayerSnapshot('closed-500ms');},500);setTimeout(function(){menuLayerSnapshot('closed-1500ms');},1500);}});menuLifecycleObserver.observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['aria-expanded','aria-hidden','hidden','style']});}"
      "function runMenuInitProbe(){if(menuProbeDone)return;if(!postSent){setTimeout(runMenuInitProbe,250);return;}if(location.pathname!=='/home')return;var btn=document.querySelector('[data-testid=DashButton_ProfileIcon_Link]');if(!btn){send('menu-init-probe-missing',{selector:'DashButton_ProfileIcon_Link'});return;}menuProbeDone=true;var before=summarizeMenuState();var beforeResources=compactSummary();send('menu-init-probe-ready',{state:before,resources:beforeResources});setTimeout(function(){var after=summarizeMenuState();var now=compactSummary();var types={};Object.keys(now.byType).forEach(function(k){var a=now.byType[k],b=beforeResources.byType[k]||{count:0,totalDuration:0,maxDuration:0};var dc=a.count-b.count,dd=a.totalDuration-b.totalDuration;if(dc>0||dd>0)types[k]={count:dc,totalDuration:dd,maxDuration:a.maxDuration};});send('menu-init-probe-idle',{windowMs:1500,state:after,resourceCount:now.count-beforeResources.count,totalResourceDuration:now.totalDuration-beforeResources.totalDuration,byType:types});},1500);}"
      "if((window.__scarletXDiagnostics||{}).menu)setTimeout(runMenuInitProbe,100);";
}

+ (NSString *)menuWarmupScript {
    return @"var hiddenMenuWarmupDone=false,hiddenMenuWarmupActive=false,hiddenMenuWarmupNode=null,hiddenMenuWarmupResources=null,hiddenMenuWarmupResourceTimersStarted=false;"
      "function nativeDrawerEnabled(){return !!window.__scarletXNativeDrawerInstalled;}"
      "function hiddenMenuWarmupTrace(stage,payload){try{window.webkit.messageHandlers.scarletx.postMessage({type:'native-drawer-trace',stage:stage,error:JSON.stringify(payload||{})});}catch(e){}}"
      "function accountDomProbe(label){try{var labels=[],links=[],pics=[];Array.from(document.querySelectorAll('[aria-label]')).forEach(function(el){var v=el.getAttribute('aria-label')||'';if(v.indexOf('@')>=0||v.indexOf('プロフィール')>=0)labels.push(v);});Array.from(document.querySelectorAll('a[href]')).forEach(function(el){var v=el.getAttribute('href')||'';if(v.length>1&&v.split('/').length===2)links.push(v);});Array.from(document.images||[]).forEach(function(img){var src=img.currentSrc||img.src||'';if(src.indexOf('profile_images')>=0)pics.push(src);});hiddenMenuWarmupTrace('account-dom-'+label,{state:summarizeMenuState(),labels:Array.from(new Set(labels)).slice(0,30),profileLinks:Array.from(new Set(links)).slice(0,30),profileImageCount:(new Set(pics)).size});}catch(e){hiddenMenuWarmupTrace('account-dom-error',{label:label,message:String(e)});}}"
      "function accountReactProbe(label){try{var root=document.querySelector('[data-testid=DashButton_ProfileIcon_Link]')||document.querySelector('[data-testid=primaryColumn]')||document.body;if(!root){hiddenMenuWarmupTrace('account-react-'+label,{found:false});return;}var seen=new Set(),results=[];function pick(obj,path,depth){if(!obj||typeof obj!=='object'||seen.has(obj)||depth>5||results.length>=40)return;seen.add(obj);var out={};['screen_name','username','name','profile_image_url_https','rest_id'].forEach(function(k){try{var v=obj[k];if(typeof v==='string'&&v.length&&v.length<500)out[k]=v;}catch(e){}});if(Object.keys(out).length)results.push({path:path,values:out});var keys=[];try{keys=Object.keys(obj);}catch(e){return;}keys.slice(0,80).forEach(function(k){if(results.length>=40)return;if(k==='return'||k==='sibling'||k==='child'||k==='stateNode'||k==='alternate')return;var v;try{v=obj[k];}catch(e){return;}if(v&&typeof v==='object')pick(v,path+'.'+k,depth+1);});}var owners=[];for(var el=root,hop=0;el&&hop<5;hop++,el=el.parentElement){var ks=[];try{ks=Object.keys(el);}catch(e){}ks.forEach(function(k){if(k.indexOf('__reactProps$')===0||k.indexOf('__reactFiber$')===0){owners.push({hop:hop,key:k.slice(0,24)});try{pick(el[k],'node['+hop+'].'+k.slice(0,12),0);}catch(e){}}});}hiddenMenuWarmupTrace('account-react-'+label,{state:summarizeMenuState(),ownerCount:owners.length,owners:owners,results:results});}catch(e){hiddenMenuWarmupTrace('account-react-error',{label:label,message:String(e)});}}"
      "function fiberTypeName(f){try{var t=f&&f.type;if(typeof t==='string')return t;if(t&&typeof t.displayName==='string')return t.displayName;if(t&&typeof t.name==='string')return t.name;var e=f&&f.elementType;if(typeof e==='string')return e;if(e&&typeof e.displayName==='string')return e.displayName;if(e&&typeof e.name==='string')return e.name;}catch(e){}return '';}"
      "function fiberValueShape(v){try{if(v==null)return String(v);if(Array.isArray(v))return 'array('+v.length+')';var t=typeof v;if(t!=='object')return t;var ks=Object.keys(v);return 'object:'+ks.slice(0,24).join(',');}catch(e){return 'unreadable';}}"
      "function buildFiberChain(node,maxDepth){var fiber=null,fiberKey='',keys=[];try{keys=Object.keys(node||{});}catch(e){}for(var i=0;i<keys.length;i++){if(keys[i].indexOf('__reactFiber$')===0){fiber=node[keys[i]];fiberKey=keys[i].slice(0,28);break;}}if(!fiber)return {fiberFound:false,fiberKey:fiberKey,chain:[]};var chain=[],f=fiber;for(var depth=0;f&&depth<(maxDepth||24);depth++,f=f.return){var pKeys=[],sKeys=[],stType='';try{if(f.memoizedProps&&typeof f.memoizedProps==='object')pKeys=Object.keys(f.memoizedProps).slice(0,40);}catch(e){}try{if(f.memoizedState&&typeof f.memoizedState==='object')sKeys=Object.keys(f.memoizedState).slice(0,40);}catch(e){}try{stType=f.stateNode&&f.stateNode.constructor&&f.stateNode.constructor.name||typeof f.stateNode;}catch(e){}chain.push({depth:depth,tag:f.tag,type:fiberTypeName(f),propsKeys:pKeys,stateShape:fiberValueShape(f.memoizedState),stateKeys:sKeys,stateNodeType:stType});}return {fiberFound:true,fiberKey:fiberKey,chain:chain};}"
      "function collectAccountIdentity(root){var results=[],seen=new Set();function walk(v,path,depth){if(!v||typeof v!=='object'||seen.has(v)||depth>5||results.length>=32)return;seen.add(v);var out={};['rest_id','screen_name','username','name','profile_image_url_https'].forEach(function(k){try{var x=v[k];if(typeof x==='string'&&x.length&&x.length<500)out[k]=x;}catch(e){}});if(Object.keys(out).length)results.push({path:path,values:out});var keys=[];try{keys=Object.keys(v);}catch(e){return;}keys.slice(0,60).forEach(function(k){if(results.length>=32)return;var x;try{x=v[k];}catch(e){return;}if(x&&typeof x==='object')walk(x,path+'.'+k,depth+1);});}walk(root,'root',0);return results;}"
      "function findAccountCollections(root){var out=[],seen=new Set();function walk(v,path,depth){if(!v||typeof v!=='object'||seen.has(v)||depth>6||out.length>=20)return;seen.add(v);var ids=collectAccountIdentity(v);if(ids.length>=2){out.push({path:path,shape:fiberValueShape(v),identity:ids.slice(0,8)});if(out.length>=20)return;}var keys=[];try{keys=Object.keys(v);}catch(e){return;}keys.slice(0,80).forEach(function(k){if(out.length>=20)return;if(k==='window'||k==='document'||k==='ownerDocument'||k==='parentNode'||k==='childNodes')return;var x;try{x=v[k];}catch(e){return;}if(x&&typeof x==='object')walk(x,path+'.'+k,depth+1);});}walk(root,'root',0);return out;}"
      "function summarizeStoreCandidate(v,path){try{if(!v||typeof v!=='object')return null;var store=v.store&&typeof v.store==='object'?v.store:v;var getState=store&&store.getState,subscribe=store&&store.subscribe,dispatch=store&&store.dispatch;if(typeof getState!=='function'&&typeof subscribe!=='function'&&typeof dispatch!=='function')return null;var state=null,stateKeys=[],accountPaths=[];if(typeof getState==='function'){try{state=getState.call(store);if(state&&typeof state==='object')stateKeys=Object.keys(state).slice(0,80);accountPaths=findAccountCollections(state);}catch(e){}}return {path:path,storeKeys:Object.keys(store).slice(0,40),getStateType:typeof getState,subscribeType:typeof subscribe,dispatchType:typeof dispatch,stateKeys:stateKeys,accountPaths:accountPaths};}catch(e){return {path:path,error:String(e)};}}"
      "function summarizeFiberDependencies(f,depth){var out={depth:depth,type:fiberTypeName(f),tag:f?f.tag:null,propsKeys:[],stateShape:'',updateQueueKeys:[],dependencyKeys:[],contexts:[],storeCandidates:[]};try{if(f.memoizedProps&&typeof f.memoizedProps==='object')out.propsKeys=Object.keys(f.memoizedProps).slice(0,50);}catch(e){}try{out.stateShape=fiberValueShape(f.memoizedState);}catch(e){}try{if(f.updateQueue&&typeof f.updateQueue==='object')out.updateQueueKeys=Object.keys(f.updateQueue).slice(0,40);}catch(e){}var deps=null;try{deps=f.dependencies;if(deps&&typeof deps==='object')out.dependencyKeys=Object.keys(deps).slice(0,30);}catch(e){}var c=null;try{c=deps&&deps.firstContext;}catch(e){}for(var i=0;c&&i<8;i++){var mv=null,ctx=null;try{mv=c.memoizedValue;}catch(e){}try{ctx=c.context;}catch(e){}var info={index:i,contextKeys:[],memoizedValueShape:fiberValueShape(mv),memoizedValueKeys:[]};try{if(ctx&&typeof ctx==='object')info.contextKeys=Object.keys(ctx).slice(0,30);}catch(e){}try{if(mv&&typeof mv==='object')info.memoizedValueKeys=Object.keys(mv).slice(0,40);}catch(e){}out.contexts.push(info);var sc=summarizeStoreCandidate(mv,'fiber['+depth+'].context['+i+'].memoizedValue');if(sc)out.storeCandidates.push(sc);try{if(ctx&&typeof ctx==='object'){var cv=ctx._currentValue2!==undefined?ctx._currentValue2:ctx._currentValue;var sc2=summarizeStoreCandidate(cv,'fiber['+depth+'].context['+i+'].currentValue');if(sc2)out.storeCandidates.push(sc2);}}catch(e){}try{c=c.next;}catch(e){break;}}var direct=summarizeStoreCandidate(f.memoizedProps,'fiber['+depth+'].memoizedProps');if(direct)out.storeCandidates.push(direct);return out;}"
      "function traceSwitchRowFiber(label){try{var rows=Array.from(document.querySelectorAll('button[aria-label$=\"に切り替える\"]'));if(!rows.length){hiddenMenuWarmupTrace('fiber-switch-'+label,{found:false,rowCount:0,state:summarizeMenuState()});return;}var row=rows[0],aria=row.getAttribute('aria-label')||'',r=buildFiberChain(row,24),fiber=null,keys=[];try{keys=Object.keys(row);}catch(e){}for(var i=0;i<keys.length;i++){if(keys[i].indexOf('__reactFiber$')===0){fiber=row[keys[i]];break;}}var accountSource=null,sourceDepth=-1,f=fiber;for(var depth=0;f&&depth<24;depth++,f=f.return){var p=f.memoizedProps;if(p&&typeof p==='object'&&Object.prototype.hasOwnProperty.call(p,'multiAccountUsers')){var mau=p.multiAccountUsers;sourceDepth=depth;accountSource={depth:depth,type:fiberTypeName(f),multiAccountUsersType:Array.isArray(mau)?'array':typeof mau,multiAccountUsersCount:Array.isArray(mau)?mau.length:null,multiAccountUsersShape:fiberValueShape(mau),identity:collectAccountIdentity(mau),delegateUserType:typeof p.delegateUser,switchAccountType:typeof p.switchAccount,showMultiAccountOverflowPipType:typeof p.showMultiAccountOverflowPip};break;}}var upstream=[];if(sourceDepth>=0){f=fiber;for(var skip=0;f&&skip<sourceDepth;skip++)f=f.return;for(var j=0;f&&j<8;j++,f=f.return)upstream.push(summarizeFiberDependencies(f,sourceDepth+j));}hiddenMenuWarmupTrace('fiber-switch-'+label,{found:true,rowCount:rows.length,aria:aria,fiberFound:r.fiberFound,fiberKey:r.fiberKey,chain:r.chain,accountSource:accountSource,upstream:upstream});}catch(e){hiddenMenuWarmupTrace('fiber-switch-error',{label:label,message:String(e)});}}"
      "function findCurrentAccountNode(){var dialog=document.querySelector('[role=dialog]');if(!dialog)return null;var links=Array.from(dialog.querySelectorAll('a[href]'));for(var i=0;i<links.length;i++){var a=links[i],href=a.getAttribute('href')||'';if(!/^\\/[A-Za-z0-9_]+$/.test(href))continue;if(href==='/settings'||href==='/logout'||href==='/home'||href==='/explore'||href==='/notifications'||href==='/messages'||href==='/compose')continue;if(a.querySelector('img[src*=\"profile_images\"]')||a.querySelector('img'))return a;}for(var j=0;j<links.length;j++){var h=links[j].getAttribute('href')||'';if(/^\\/[A-Za-z0-9_]+$/.test(h)&&h!=='/settings'&&h!=='/logout')return links[j];}return null;}"
      "function traceCurrentAccountFiber(label){try{var node=findCurrentAccountNode();if(!node){hiddenMenuWarmupTrace('fiber-current-'+label,{found:false,state:summarizeMenuState()});return;}var href=node.getAttribute('href')||'',r=buildFiberChain(node,24);hiddenMenuWarmupTrace('fiber-current-'+label,{found:true,href:href,fiberFound:r.fiberFound,fiberKey:r.fiberKey,chain:r.chain});}catch(e){hiddenMenuWarmupTrace('fiber-current-error',{label:label,message:String(e)});}}"
      "function scheduleFiberTrace(){traceCurrentAccountFiber('0ms');traceSwitchRowFiber('0ms');setTimeout(function(){traceCurrentAccountFiber('25ms');traceSwitchRowFiber('25ms');},25);setTimeout(function(){traceCurrentAccountFiber('100ms');traceSwitchRowFiber('100ms');},100);setTimeout(function(){traceCurrentAccountFiber('250ms');traceSwitchRowFiber('250ms');},250);setTimeout(function(){traceSwitchRowFiber('500ms');},500);setTimeout(function(){traceSwitchRowFiber('700ms');},700);}"
      "function hiddenMenuWarmupResourceDelta(label){if(!hiddenMenuWarmupResources)return;var now=compactSummary(),before=hiddenMenuWarmupResources,types={};Object.keys(now.byType).forEach(function(k){var a=now.byType[k],b=before.byType[k]||{count:0,totalDuration:0,maxDuration:0};var dc=a.count-b.count,dd=a.totalDuration-b.totalDuration;if(dc>0||dd>0)types[k]={count:dc,totalDuration:dd,maxDuration:a.maxDuration};});var payload={label:label,resourceCount:now.count-before.count,totalResourceDuration:now.totalDuration-before.totalDuration,byType:types,state:summarizeMenuState()};hiddenMenuWarmupTrace('warmup-resources-'+label,payload);send('menu-hidden-warmup-resources',payload);}"
      "function startHiddenMenuWarmupResourceTimers(){if(hiddenMenuWarmupResourceTimersStarted)return;hiddenMenuWarmupResourceTimersStarted=true;hiddenMenuWarmupResourceDelta('dialog-mounted');setTimeout(function(){hiddenMenuWarmupResourceDelta('after-250ms');},250);setTimeout(function(){hiddenMenuWarmupResourceDelta('after-750ms');},750);setTimeout(function(){hiddenMenuWarmupResourceDelta('after-1500ms');},1500);}"
      "function finishHiddenMenuWarmup(reason){if(!hiddenMenuWarmupActive)return;hiddenMenuWarmupActive=false;var btn=document.querySelector('[data-testid=DashButton_ProfileIcon_Link]');if(btn&&btn.getAttribute('aria-expanded')==='true'){try{btn.click();}catch(e){try{document.body.click();}catch(e2){}}}if(hiddenMenuWarmupNode){hiddenMenuWarmupNode.style.removeProperty('opacity');hiddenMenuWarmupNode.style.removeProperty('pointer-events');hiddenMenuWarmupNode.style.removeProperty('transform');hiddenMenuWarmupNode=null;}hiddenMenuWarmupTrace('warmup-finish',{reason:reason,state:summarizeMenuState()});send('menu-hidden-warmup-finish',{reason:reason,state:summarizeMenuState()});}"
      "var hiddenMenuObserver=new MutationObserver(function(){if(!hiddenMenuWarmupActive)return;var layers=document.getElementById('layers');if(!layers)return;var s=summarizeMenuState();if(s.profileExpanded==='true'&&s.dialogs>0&&layers.children.length>2){var node=layers.lastElementChild;if(node&&!hiddenMenuWarmupNode){hiddenMenuWarmupNode=node;node.style.setProperty('opacity','0','important');node.style.setProperty('pointer-events','none','important');node.style.setProperty('transform','translateX(-200vw)','important');hiddenMenuWarmupTrace('warmup-mounted',{state:s});accountDomProbe('after-menu-dom');accountReactProbe('after-menu-dom');scheduleFiberTrace();send('menu-hidden-warmup-mounted',{state:s});startHiddenMenuWarmupResourceTimers();setTimeout(function(){finishHiddenMenuWarmup('mounted-700ms');},700);}}});hiddenMenuObserver.observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['aria-expanded']});"
      "function runHiddenMenuWarmup(){if(hiddenMenuWarmupDone||hiddenMenuWarmupActive||!postSent||location.pathname!=='/home'){if(!postSent)setTimeout(runHiddenMenuWarmup,250);return;}var btn=document.querySelector('[data-testid=DashButton_ProfileIcon_Link]');if(!btn)return;hiddenMenuWarmupDone=true;hiddenMenuWarmupActive=true;hiddenMenuWarmupResources=compactSummary();hiddenMenuWarmupResourceTimersStarted=false;accountDomProbe('before-menu');accountReactProbe('before-menu');var payload={state:summarizeMenuState(),resources:hiddenMenuWarmupResources,nativeDrawer:nativeDrawerEnabled()};hiddenMenuWarmupTrace('warmup-start',payload);send('menu-hidden-warmup-start',payload);try{btn.click();}catch(e){hiddenMenuWarmupActive=false;hiddenMenuWarmupTrace('warmup-error',{message:String(e)});send('menu-hidden-warmup-error',{message:String(e)});return;}setTimeout(function(){finishHiddenMenuWarmup('timeout-1500ms');},1500);}"
      "setTimeout(runHiddenMenuWarmup,100);";
}
@end
